-- 0052_demo_schema.sql — schema `demo`: the labelled Del Monte demonstration pipeline's tables.
--
-- Approved by Kelvin 2026-10-15 (Sir Catubag informed); recorded in CLAUDE.md hard rule 2 so a later session
-- does not revert it. This migration creates structure only: no row is written to any existing table, and
-- nothing in public reads or joins to demo.*. Rows are generated by scripts/build_dm_demo.py, which reads real
-- Del Monte sell-out only through SellOut_Fact_Real and writes only demo.*.
--
-- RAILS, enforced by the table definitions themselves:
--   * every row: is_demo = true (CHECK) and fill_source = 'synthetic_dm_pipeline_demo' (CHECK)
--   * NO accuracy column in any demo table (no mape / mase / wape / smape / rmse) and no confidence band
--     (no lower / upper / interval). tests/test_demo_schema.py fails if one is ever added to this file.
--   * a demo forecast is its own demo.run; it never joins a real cohort, and forecast_result is untouched
--     (run_baseline_forecast --write deletes orphan forecast_result rows, so Del Monte must not live there).
--   * Unilever is not in this schema: its gaps are real zero-sale months, so it has nothing to fill.
--
-- Expected after applying: schema demo with 5 tables, all empty; public row counts unchanged.
-- Rollback: DROP SCHEMA demo CASCADE;   (nothing outside demo depends on it)

CREATE SCHEMA IF NOT EXISTS demo;

COMMENT ON SCHEMA demo IS
    'Synthetic Del Monte demonstration pipeline (CLAUDE.md rule 2, approved 2026-10-15). Generated data only; '
    'never read by a _Real view, a real forecast, accuracy or the LP. Migration 0052.';

-- One row per generator run: everything needed to regenerate it identically.
CREATE TABLE IF NOT EXISTS demo.run (
    run_id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    label             TEXT        NOT NULL DEFAULT 'demonstration',
    principal         TEXT        NOT NULL CHECK (principal = 'delmonte'),
    seed              BIGINT      NOT NULL,           -- per-series streams are derived from (seed, category_path)
    generator_version TEXT        NOT NULL,
    jitter_scale      NUMERIC     NOT NULL,           -- jitter sd = jitter_scale x the series' own CV x the interpolated value
    window_end        TEXT        NOT NULL,           -- 'YYYY-MM': last month a series may use (real sales end 2025-12)
    forecast_target   TEXT        NOT NULL,           -- 'YYYY-MM': the one month forecast
    cost_ratio        NUMERIC     NOT NULL,           -- Unilever's observed median cost-to-price ratio, applied to Del Monte
    cost_ratio_source TEXT        NOT NULL,           -- the query behind it, in words, with its n
    approved_by       TEXT        NOT NULL,
    approved_on       DATE        NOT NULL,
    notes             JSONB,
    is_demo           BOOLEAN     NOT NULL DEFAULT true CHECK (is_demo),
    fill_source       TEXT        NOT NULL DEFAULT 'synthetic_dm_pipeline_demo'
                      CHECK (fill_source = 'synthetic_dm_pipeline_demo'),
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Monthly sales per category: real months copied, in-span gaps interpolated between two real months.
CREATE TABLE IF NOT EXISTS demo.dm_category_sales (
    run_id        BIGINT      NOT NULL REFERENCES demo.run (run_id) ON DELETE CASCADE,
    category_path TEXT        NOT NULL,
    product_key   BIGINT,                              -- Product_Dimension grain='category' row (no FK on purpose)
    period        TEXT        NOT NULL CHECK (period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
    quantity      NUMERIC(14,2),
    net_amount    NUMERIC(14,2),
    origin        TEXT        NOT NULL CHECK (origin IN ('real_copy', 'interpolated')),
    is_demo       BOOLEAN     NOT NULL DEFAULT true CHECK (is_demo),
    fill_source   TEXT        NOT NULL DEFAULT 'synthetic_dm_pipeline_demo'
                  CHECK (fill_source = 'synthetic_dm_pipeline_demo'),
    PRIMARY KEY (run_id, category_path, period)
);

-- Per category: price, cost and lead time the demo plan would use, each with where it came from.
CREATE TABLE IF NOT EXISTS demo.dm_category_param (
    run_id             BIGINT      NOT NULL REFERENCES demo.run (run_id) ON DELETE CASCADE,
    category_path      TEXT        NOT NULL,
    product_key        BIGINT,
    unit_price         NUMERIC(14,4),                  -- real SUM(net_amount)/SUM(quantity) over months with both > 0
    unit_cost          NUMERIC(14,4),                  -- unit_price x demo.run.cost_ratio
    cost_source        TEXT        NOT NULL DEFAULT 'unilever_median_cost_to_price_ratio',
    lead_time_days     INTEGER,                        -- COPIED from Product_Dimension, never generated
    lead_time_source   TEXT,                           -- copied with it ('pending_confirmation' until SSM confirms)
    first_real_period  TEXT        NOT NULL,
    last_real_period   TEXT        NOT NULL,
    real_months        INTEGER     NOT NULL,
    interpolated_months INTEGER    NOT NULL,
    forecast_status    TEXT        NOT NULL CHECK (forecast_status IN ('ok', 'series_ended_before_window_end')),
    is_demo            BOOLEAN     NOT NULL DEFAULT true CHECK (is_demo),
    fill_source        TEXT        NOT NULL DEFAULT 'synthetic_dm_pipeline_demo'
                       CHECK (fill_source = 'synthetic_dm_pipeline_demo'),
    PRIMARY KEY (run_id, category_path)
);

-- One-step MA3 (the deployed method, analytics/forecasting/baseline.moving_average_forecast) per category.
-- No error metric and no band: the demonstration path never scores a forecast against generated months.
CREATE TABLE IF NOT EXISTS demo.dm_forecast (
    run_id            BIGINT      NOT NULL REFERENCES demo.run (run_id) ON DELETE CASCADE,
    category_path     TEXT        NOT NULL,
    product_key       BIGINT,
    forecast_period   TEXT        NOT NULL CHECK (forecast_period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
    forecast_quantity NUMERIC(14,2) NOT NULL,
    method            TEXT        NOT NULL CHECK (method = 'ma3'),
    history_months    INTEGER     NOT NULL,            -- months of series history up to window_end
    interpolated_in_window INTEGER NOT NULL,           -- how many of the 3 averaged months were generated
    is_demo           BOOLEAN     NOT NULL DEFAULT true CHECK (is_demo),
    fill_source       TEXT        NOT NULL DEFAULT 'synthetic_dm_pipeline_demo'
                      CHECK (fill_source = 'synthetic_dm_pipeline_demo'),
    PRIMARY KEY (run_id, category_path, forecast_period)
);

-- Series left out of the demo, named, with why. Nothing is invented to rescue them.
CREATE TABLE IF NOT EXISTS demo.dm_excluded (
    run_id        BIGINT      NOT NULL REFERENCES demo.run (run_id) ON DELETE CASCADE,
    category_path TEXT        NOT NULL,
    reason        TEXT        NOT NULL,
    real_months   INTEGER     NOT NULL,
    first_real_period TEXT,
    last_real_period  TEXT,
    is_demo       BOOLEAN     NOT NULL DEFAULT true CHECK (is_demo),
    fill_source   TEXT        NOT NULL DEFAULT 'synthetic_dm_pipeline_demo'
                  CHECK (fill_source = 'synthetic_dm_pipeline_demo'),
    PRIMARY KEY (run_id, category_path)
);

-- Not exposed to the Supabase client roles; the backend connects as the owner.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
        EXECUTE 'REVOKE ALL ON SCHEMA demo FROM anon';
        EXECUTE 'REVOKE ALL ON ALL TABLES IN SCHEMA demo FROM anon';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
        EXECUTE 'REVOKE ALL ON SCHEMA demo FROM authenticated';
        EXECUTE 'REVOKE ALL ON ALL TABLES IN SCHEMA demo FROM authenticated';
    END IF;
END
$$;
